rss.channel:
    {{ site.title | default: site.name | xml_escape }}
    {{ "/" | absolute_url }}
    {{ site.description | xml_escape }}
    {%- if site.lang %}
    {{ site.lang }}
    {%- endif %}
    {{ site.time | date_to_rfc822 }}

{%- for post in posts %}
  {%- assign post_url = post.url | absolute_url %}


      {{ post.title | strip_html | strip | xml_escape }}
      {{ post_url }}
      {{ post_url }}
      {{ post.date | date_to_rfc822 }}
    {%- comment -%} devto_tags first, so new imports already carry the tags chosen for dev.to. {%- endcomment -%}
    {%- assign devto_tags = post.devto_tags | devto_list %}
    {%- assign tags = devto_tags | default: post.tags | default: post.categories %}
    {%- for tag in tags %}
      {{ tag | xml_escape }}
    {%- endfor %}
      {{ post.description | default: post.excerpt | strip_html | strip_newlines | truncatewords: 60 | xml_escape }}
    {%- comment -%}
      The dev.to cover is opt-in: many Open Graph images carry the post title, which dev.to
      already shows under the cover, and without one dev.to generates its own share image.
      devto_cover on a post always wins (false turns it off, true uses the post image);
      `devto: { cover: image }` in _config.yml uses each post's image. Unlike content
      links, image paths leave baseurl out (Chirpy and jekyll-og-image add it when
      rendering), so the cover needs it.
    {%- endcomment -%}
    {%- assign cover = "" %}
    {%- if post.devto_cover == false %}
    {%- elsif post.devto_cover == true %}
      {%- assign cover = post.image | devto_url: site_root %}
    {%- elsif post.devto_cover %}
      {%- assign cover = post.devto_cover | devto_url: site_root %}
    {%- elsif devto.cover == "image" or devto.cover == true %}
      {%- assign cover = post.image | devto_url: site_root %}
    {%- endif %}
    {%- if cover != "" %}
      {{ cover | xml_escape }}
    {%- endif %}
    {%- if devto_tags %}
      {{ devto_tags | join: "," | xml_escape }}
    {%- endif %}
    {%- if post.devto_series %}
      {{ post.devto_series | xml_escape }}
    {%- endif %}
      {{ post.content | devto_html: site_url | xml_escape }}

{%- endfor %}
